      planning: () => ({ name: 'kanban', query: { view: 'planning' } })
    },
    messenger: {
      open: () => ({ name: 'messenger' })
    },
    git: {
      open: () => ({ name: 'git-view' })
    },
    desktop: {
      open: () => ({ name: 'codx-junior-split' })
    },
    mobile: {
      open: () => ({ name: 'mobile' })
    },
    home: {
      open: () => homeLocation()
    }
  }

  // ════════════════════════════════════════════════════════════════
  // MODE DETECTION - Single vs Desktop
  //
  // The ACTIVE ROUTE defines the mode (never the screen width or a ui
  // store flag):
